// Toast notification helper
function showToast(msg, type) {
	var t = document.createElement("div");
	t.className =
		"toast-notification" +
		(type === "error"
			? " toast-error"
			: type === "success"
				? " toast-success"
				: "");
	t.textContent = msg;
	document.body.appendChild(t);
	setTimeout(function () {
		t.classList.add("show");
	}, 10);
	setTimeout(function () {
		t.remove();
	}, 3000);
}

