		_origAF.call(this);
		if (this._dateField && (this._dateFrom || this._dateTo)) {
			var fromT = this._dateFrom ? _parseDate(this._dateFrom) : null;
			var toT = this._dateTo ? _parseDate(this._dateTo) : null;
			var fld = this._dateField;
			this.filteredData = this.filteredData.filter(function (row) {
				var dv = _parseDate(row[fld]);
				if (dv == null) return false;
				if (fromT != null && dv < fromT) return false;
				if (toT != null && dv > toT + 86399999) return false;
				return true;
			});
		}
