DashboardViewModel.prototype.alphaField = "Student Information";
DashboardViewModel.prototype.alphaRanges = [
	["A", "H"],
	["I", "P"],
	["Q", "Z"],
];

DashboardViewModel.prototype.render = function () {
	var container = document.getElementById("dashboardContent");
	if (!container) return;
	var self = this;
	container.innerHTML = this.alphaRanges
		.map(function (range) {
			var label = range[0] + " - " + range[1];
			var rows = self.filteredData.filter(function (row) {
				var val = (row[self.alphaField] || "").charAt(0).toUpperCase();
				return val >= range[0] && val <= range[1];
			});
			return self.renderSwimlane({ name: label }, rows);
		})
		.join("");
};

DashboardViewModel.prototype.renderSwimlane = function (swimlane, rows) {
	var self = this;
	var colHeaders = this.config.columns
		.map(function (col) {
			return _sortHeader(col.field, col.label);
		})
		.join("");
	var rowsHtml = rows
		.map(function (row) {
			var cells = self.config.columns
				.map(function (col) {
					return _cell(row, col);
				})
				.join("");
			return (
				"<tr>" +
				cells +
				'<td><a href="' +
				encodeURI(_safeUrl(row.url || "#")) +
				'" target="_blank" class="view-btn"><i class="bi bi-eye"></i> View</a></td></tr>'
			);
		})
		.join("");
	return (
		'<div class="swimlane"><div class="swimlane-header" onclick="toggleSwimlane(this)">' +
		'<i class="bi bi-chevron-down"></i><span>' +
		_esc(swimlane.name) +
		'</span><span class="count">' +
		rows.length +
		"</span></div>" +
		'<div class="swimlane-content"><table class="data-table"><thead><tr>' +
		colHeaders +
		"<th>Actions</th></tr></thead>" +
		"<tbody>" +
		rowsHtml +
		"</tbody></table></div></div>"
	);
};

// ===== SUMMARY CHART (counts per swimlane) =====
(function () {
	if (typeof DashboardViewModel === "undefined") return;
	var _origR = DashboardViewModel.prototype.render;
	DashboardViewModel.prototype.render = function () {
		if (_origR) _origR.call(this);
		try {
			_renderSummaryChart(this);
		} catch (e) {}
	};
})();
function _renderSummaryChart(vm) {
	var el = document.getElementById("dashboardChart");
	if (!el || !vm || !vm.config || !vm.config.swimlanes) return;
	var lanes = vm.config.swimlanes;
	var counts = lanes.map(function (sl) {
		return { name: sl.name, n: vm.getRowsForSwimlane(sl).length };
	});
	var total = counts.reduce(function (a, c) {
		return a + c.n;
	}, 0);
	if (lanes.length < 2 || total === 0) {
		el.style.display = "none";
		return;
	}
	var max =
		counts.reduce(function (a, c) {
			return Math.max(a, c.n);
		}, 0) || 1;
	var rowsHtml = counts
		.map(function (c) {
			var pct = Math.round((c.n / max) * 100);
			return (
				'<div class=\"chart-row\"><span class=\"chart-label\" title=\"' +
				_esc(c.name) +
				'\">' +
				_esc(c.name) +
				'</span><span class=\"chart-bar-wrap\"><span class=\"chart-bar\" style=\"width:' +
				pct +
				'%;\"></span></span><span class=\"chart-val\">' +
				c.n +
				"</span></div>"
			);
		})
		.join("");
	el.innerHTML =
		'<h3 onclick=\"toggleChart(this)\"><i class=\"bi bi-bar-chart-fill\"></i> Overview: ' +
		total +
		" item" +
		(total === 1 ? "" : "s") +
		'<i class=\"bi bi-chevron-down\" style=\"margin-left:auto;font-size:0.8rem;\"></i></h3><div class=\"chart-body\">' +
		rowsHtml +
		"</div>";
	el.style.display = "block";
}
function toggleChart(h) {
	var c = h.closest(".summary-chart");
	if (c) c.classList.toggle("collapsed");
}

console.log("[Dashboard v4.4] viewmodel.js loaded");

function toggleSwimlane(header) {
	var content = header.nextElementSibling;
	var icon = header.querySelector("i");
	content.classList.toggle("collapsed");
	icon.classList.toggle("bi-chevron-down");
	icon.classList.toggle("bi-chevron-right");
}

